  scene.userData.sphNativeMarchingCubesAdapterCache = null;
  scene.userData.sphPressureInterfaceForceRowsUpload = null;

  function markSurfaceActive(surface) {
    surface.inactiveFrameCount = 0;
    surface.mesh.userData.surfaceInactiveFrameCount = 0;
  }

  function hideSurfaceAfterGrace(surface, renderSource, options = {}) {
    return hideRenderFieldSurfaceAfterGrace(surface, renderSource, options);
  }

  function materialListOf(material) {
    if (Array.isArray(material)) return material.filter(Boolean);
    return material ? [material] : [];
  }

  function isOpticalGpuDrawTarget(node) {
    if (!node?.material) return false;
    const renderMode = node.userData?.renderMode;
    return renderMode === SPH_PHASE_RENDER_MODE
      || renderMode === SPH_THREE_RENDER_ROW_POINTS_BRIDGE_MODE
      || renderMode === SPH_THREE_RENDER_ROW_SPHERES_BRIDGE_MODE
      || renderMode === 'resident-surface-draw-three-compact'
      || renderMode === 'resident-surface-draw-three-webgpu-buffers';
  }

  function opticalGpuDrawDescriptorForNode(node, fallback = {}) {
    const userData = node?.userData || {};
    if (
      !userData.materialKey
      && !userData.renderKey
      && !userData.phase
      && !fallback.material
      && !fallback.renderKey
      && !fallback.phase
    ) {
      return null;
    }
    return renderDescriptorOf({
      renderKey: userData.renderKey ?? fallback.renderKey ?? fallback.material,
      material: userData.materialKey ?? fallback.material,
      phase: userData.phase ?? fallback.phase,
      opticalState: userData.opticalState ?? fallback.opticalState ?? null,
      renderDomainId: userData.renderDomainId ?? fallback.renderDomainId ?? 0,
      renderDomainKey: userData.renderDomainKey ?? fallback.renderDomainKey ?? null
    });
  }

  function opticalGpuDrawTargetMatchesRow(node, row, surfaceKey) {
    const userData = node?.userData || {};
    if (surfaceKey && userData.surfaceKey === surfaceKey) return true;
    const descriptor = opticalGpuDrawDescriptorForNode(node, row);
    if (!descriptor) return false;
    if (surfaceKey && descriptor.surfaceKey === surfaceKey) return true;
    if (row.material && descriptor.material !== row.material) return false;
    if (row.phase && descriptor.phase !== row.phase) return false;
    const rowStateKey = stableOpticalStateKey(row.opticalState);
    return (descriptor.opticalStateKey || 'default') === rowStateKey;
  }

  function collectOpticalGpuDrawTargetsForRow(row, surfaceKey) {
    const targets = [];
    const seen = new Set();
    const addTarget = (node) => {
      if (!isOpticalGpuDrawTarget(node) || seen.has(node.uuid)) return;
      seen.add(node.uuid);
      targets.push(node);
    };
    const surface = surfaceKey ? surfaces.get(surfaceKey) : null;
    addTarget(surface?.mesh);
    scene.traverse((node) => {
      if (opticalGpuDrawTargetMatchesRow(node, row, surfaceKey)) addTarget(node);
    });
    return targets;
  }

  function currentOpticalGpuDrawTargetSignature() {
    const entries = [];
    scene.traverse((node) => {
      if (!isOpticalGpuDrawTarget(node)) return;
      const descriptor = opticalGpuDrawDescriptorForNode(node);
      entries.push([
        node.userData?.surfaceKey ?? descriptor?.surfaceKey ?? 'surface-unspecified',
        node.userData?.renderMode ?? 'render-mode-unspecified',
        node.userData?.renderSource ?? 'render-source-unspecified',
        node.visible ? 1 : 0,
        node.uuid
      ].join(':'));
    });
    return entries.length > 0 ? entries.sort().join('|') : 'no-optical-gpu-draw-targets';
  }

  function applyOpticalGpuRowToDrawTarget(target, row, descriptor, backend) {
    if (!target || !descriptor) return null;
    const renderAlpha = renderAlphaFromOpticalResponse(row, descriptor);
    for (const material of materialListOf(target.material)) {
      if (material.color?.setRGB) {
        material.color.setRGB(
          clamp(row.baseColorLinear[0], 0, 1),
          clamp(row.baseColorLinear[1], 0, 1),
          clamp(row.baseColorLinear[2], 0, 1),
          Three.LinearSRGBColorSpace
        );
      }
      material.opacity = renderAlpha;
      material.transparent = renderAlpha < 0.999;
      material.depthWrite = renderDepthWriteFromOpticalResponse(row, descriptor);
      if ('metalness' in material) material.metalness = clamp(row.metalness, 0, 1);
      if ('roughness' in material) material.roughness = clamp(row.roughness, 0, 1);
      if ('transmission' in material) material.transmission = clamp(row.transmission, 0, 1);
      if ('ior' in material) material.ior = Math.max(1, row.ior || 1);
      if ('vertexColors' in material) {
        material.vertexColors = target.userData?.renderMode === SPH_THREE_RENDER_ROW_SPHERES_BRIDGE_MODE
          ? false
          : row.vertexColorPolicyId === 2;
      }
      material.userData.optical = {
        ...(material.userData.optical || {}),
        ...row,
        source: 'optical-gpu-lookup-output-row'
      };
      material.userData.opticalGpuLookupRow = { ...row };
      material.needsUpdate = true;
    }
    const ordering = applySurfaceRenderOrdering(target, row, descriptor);
    const primaryMaterial = materialListOf(target.material)[0] || null;
    if (target.userData?.renderMode === SPH_THREE_RENDER_ROW_SPHERES_BRIDGE_MODE) {
      stabilizeRenderRowSphereBridgeMaterial(primaryMaterial, { descriptor });
    } else {
      stabilizeSurfaceMeshMaterialForRenderer(primaryMaterial, {
        descriptor,
        rendererMaterialPolicy: resolveSceneSurfaceMaterialRenderPolicy(),
        bridgeMode: target.userData?.renderMode || null
      });
    }
    target.userData.surfaceKey = target.userData.surfaceKey || descriptor.surfaceKey;
    target.userData.materialKey = target.userData.materialKey || descriptor.material;
    target.userData.renderKey = target.userData.renderKey || descriptor.renderKey;
    target.userData.phase = target.userData.phase || descriptor.phase;
    target.userData.optical = primaryMaterial?.userData?.optical || { ...row };
    target.userData.opticalGpuLookupOutput = { ...row, renderAlpha };
    target.userData.opticalGpuExecutionBackend = backend;
    return { target, row, ordering };
  }

  function applyOpticalGpuLookupExecution(execution, lookupState = opticalGpuLookup, {
    targetSignature = currentOpticalGpuDrawTargetSignature()
  } = {}) {
    if (!execution?.outputs) return [];
    const rows = decodeOpticalGpuLookupOutputRows(execution, lookupState.lookup);
    const applied = [];
    for (const row of rows) {
      const surfaceKey = lookupState.surfaceKeys?.[row.queryIndex];
      if (row.status === 255 || row.recordIndex < 0) continue;
      const targets = collectOpticalGpuDrawTargetsForRow(row, surfaceKey);
      for (const target of targets) {
        const descriptor = opticalGpuDrawDescriptorForNode(target, row);
        const application = applyOpticalGpuRowToDrawTarget(target, row, descriptor, execution.backend);
        if (application) applied.push({ surfaceKey, ...application });
      }
    }
    scene.userData.opticalGpuLookupDrawState = {
      schema: 'peercompute.ulg.optical-gpu-draw-state.v0',
      sourceExecutionSchema: execution.schema,
      sourceExecutionSignature: execution.signature || null,
      backend: execution.backend,
      appliedCount: applied.length,
      targetSignature,
      targetCount: targetSignature === 'no-optical-gpu-draw-targets'
        ? 0
        : targetSignature.split('|').length,
      rows,
      scientificValidation: false,
      fullPhysicsValidation: false
    };
    return applied;
  }

  function ensureOpticalGpuDrawStateCurrent() {
    const execution = opticalGpuLookup?.execution;
    if (!execution?.schema || !execution.outputs) return scene.userData.opticalGpuLookupDrawState;
    const targetSignature = currentOpticalGpuDrawTargetSignature();
    const drawState = scene.userData.opticalGpuLookupDrawState;
    if (
      drawState?.sourceExecutionSignature === (execution.signature || null)
      && drawState?.targetSignature === targetSignature
    ) {
      return drawState;
    }
    applyOpticalGpuLookupExecution(execution, opticalGpuLookup, { targetSignature });
    return scene.userData.opticalGpuLookupDrawState;
  }

  function rendererOwnedWebGpuDeviceResult() {
    const policy = resolveThreeWebGpuRendererOwnedResidentDevicePolicy({
      renderer,
      requested: enableThreeWebGpuResidentDevice,
      unsafeDiagnosticOverride: renderer.userData?.sphWebGpuPresentationUnsafeDiagnosticOverride
    });
    scene.userData.sphThreeWebGpuRendererOwnedResidentDevicePolicy = policy;
    if (!policy.rendererOwnedDeviceAllowed) {
      return null;
    }
    return {
      status: 'webgpu-renderer-owned-device-ready',
      reason: policy.reason,
      device: renderer.backend.device,
      rendererBackend: rendererBackendName(),
      rendererOwnedDevice: true,
      appOwnedRendererDevice: Boolean(threeWebGpuAppOwnedDevice),
      rendererDeviceSource: threeWebGpuRendererDeviceSource,
      rendererOwnedResidentDevicePolicy: policy,
      rendererPresentationEnabled: true,
      requiredLimits: { ...threeWebGpuRendererRequiredLimits },
      deviceLimits: summarizeThreeWebGpuDeviceLimits(renderer.backend?.device)
    };
  }

  function nativeWebGpuSurfaceConsumerDeviceResult() {
    if (!renderer?.isNativeWebGPURenderer) return null;
    const nativeConsumer = renderer.userData?.sphNativeWebGpuSurfaceConsumer
      || scene.userData?.sphNativeWebGpuSurfaceConsumer
      || null;
    const nativeDevice = nativeConsumer?.device || nativeConsumer?.gpuDevice || null;
    if (!nativeDevice || nativeConsumer?.deviceLost) return null;
    if (
      !nativeDevice.queue?.submit
      || !nativeDevice.createBuffer
      || !nativeDevice.createCommandEncoder
      || !nativeDevice.createRenderPipeline
    ) {
      return null;
    }
    return {
      status: 'webgpu-native-surface-consumer-device-ready',
      reason: 'reusing native WebGPU surface consumer resident device',
      device: nativeDevice,
      rendererBackend: rendererBackendName(),
      rendererOwnedDevice: false,
      nativeWebGpuSurfaceConsumerDevice: true,
      nativeWebGpuSurfaceConsumerStatus: nativeConsumer?.status ?? null,
      rendererOwnedResidentDevicePolicy: scene.userData.sphThreeWebGpuRendererOwnedResidentDevicePolicy
        || null,
      rendererPresentationEnabled: true,
      requiredLimits: null,
      deviceLimits: summarizeThreeWebGpuDeviceLimits(nativeDevice)
    };
  }

  async function runResidentWebGpuDeviceMapSmoke(device, {
    source = 'cached-resident-webgpu-device'
  } = {}) {
    const startedAtMs = nowMs();
    const statusBase = {
      schema: 'peercompute.ulg.sph-resident-webgpu-device-map-smoke.v0',
      source,
      startedAtMs,
      rendererBackend: rendererBackendName(),
      scientificValidation: false,
      sphValidation: false,
      fullPhysicsValidation: false
    };
    scene.userData.sphResidentWebGpuDeviceMapSmoke = {
      ...statusBase,
      status: 'pending',
      reason: 'resident WebGPU device MAP_READ smoke validation is pending',
      updatedAtMs: startedAtMs
    };
    let readback = null;
    try {
      readback = device.createBuffer({
        label: 'ulg-sph-resident-webgpu-device-map-smoke-readback',
        size: 4,
        usage: GPU_BUFFER_USAGE.MAP_READ | GPU_BUFFER_USAGE.COPY_DST
      });
      const expected = 0x12345678;
      device.queue.writeBuffer(readback, 0, new Uint32Array([expected]));
      await readback.mapAsync(GPU_MAP_MODE.READ);
      const sample = new Uint32Array(readback.getMappedRange(), 0, 1)[0];
      readback.unmap();
      readback.destroy?.();
      scene.userData.sphResidentWebGpuDeviceMapSmoke = {
        ...statusBase,
        status: sample === expected ? 'passed' : 'failed',
        reason: sample === expected
          ? 'resident WebGPU device MAP_READ smoke validation passed'
          : 'resident WebGPU device MAP_READ smoke validation returned an unexpected value',
        expected,
        sample,
        elapsedMs: Math.max(0, nowMs() - startedAtMs),
        updatedAtMs: nowMs()
      };
    } catch (error) {
      readback?.destroy?.();
      scene.userData.sphResidentWebGpuDeviceMapSmoke = {
        ...statusBase,
        status: 'error',
        reason: error instanceof Error ? error.message : String(error),
        elapsedMs: Math.max(0, nowMs() - startedAtMs),
        updatedAtMs: nowMs()
      };
    }
    return scene.userData.sphResidentWebGpuDeviceMapSmoke;
  }

  function publishResidentWebGpuDeviceTextureReadbackSmoke(record) {
    scene.userData.sphResidentWebGpuDeviceTextureReadbackSmoke = record;
    if (sphResidentSurfaceDrawRenderBridge?.rendererBridge === SPH_NATIVE_WEBGPU_SURFACE_CONSUMER_BRIDGE_MODE) {
      refreshSphNativeWebGpuSurfaceVisibleConsumerFromBridge(sphResidentSurfaceDrawRenderBridge);
    }
    return record;
  }

  async function runResidentWebGpuDeviceTextureReadbackSmoke(device, {
    source = 'cached-resident-webgpu-device'
  } = {}) {
    const startedAtMs = nowMs();
    const statusBase = {
      schema: 'peercompute.ulg.sph-resident-webgpu-device-texture-readback-smoke.v0',
      source,
      format: SPH_NATIVE_WEBGPU_SURFACE_READBACK_SMOKE_FORMAT,
      startedAtMs,
      rendererBackend: rendererBackendName(),
      scientificValidation: false,
      sphValidation: false,
      fullPhysicsValidation: false
    };
    publishResidentWebGpuDeviceTextureReadbackSmoke({
      ...statusBase,
      status: 'pending',
      reason: 'resident WebGPU device texture readback smoke validation is pending',
      updatedAtMs: startedAtMs
    });
    let validationTexture = null;
    let readback = null;
    let mapped = false;
    let timeoutHandle = null;
    const readbackBytesPerRow = 256;
    try {
      if (
        !device?.createTexture
        || !device?.createBuffer
        || !device?.createCommandEncoder
        || !device?.queue?.submit
      ) {
        throw new Error('texture readback unavailable: resident WebGPU device lacks texture, encoder, queue, or MAP_READ support');
      }
      validationTexture = device.createTexture({
        label: 'ulg-sph-resident-webgpu-device-texture-readback-smoke-target',
        size: [1, 1],
        format: SPH_NATIVE_WEBGPU_SURFACE_READBACK_SMOKE_FORMAT,
        usage: GPU_TEXTURE_USAGE.RENDER_ATTACHMENT | GPU_TEXTURE_USAGE.COPY_SRC
      });
      readback = device.createBuffer({
        label: 'ulg-sph-resident-webgpu-device-texture-readback-smoke-readback',
        size: readbackBytesPerRow,
        usage: GPU_BUFFER_USAGE.MAP_READ | GPU_BUFFER_USAGE.COPY_DST
      });
      const encoder = device.createCommandEncoder({
        label: 'ulg-sph-resident-webgpu-device-texture-readback-smoke'
      });
      const pass = encoder.beginRenderPass({
        colorAttachments: [{
          view: validationTexture.createView(),
          clearValue: { r: 1, g: 0, b: 0, a: 1 },
          loadOp: 'clear',
          storeOp: 'store'
        }]
      });
      pass.end();
      encoder.copyTextureToBuffer(
        { texture: validationTexture },
        {
          buffer: readback,
          bytesPerRow: readbackBytesPerRow,
          rowsPerImage: 1
        },
        {
          width: 1,
          height: 1,
          depthOrArrayLayers: 1
        }
      );
      device.queue.submit([encoder.finish()]);
      const mapPromise = Promise.resolve(device.queue?.onSubmittedWorkDone?.() ?? undefined)
        .then(() => readback.mapAsync(GPU_MAP_MODE.READ));
      mapPromise.catch(() => {});
      await Promise.race([
        mapPromise,
        new Promise((_, reject) => {
          timeoutHandle = setTimeout(() => {
            reject(new Error('texture readback unavailable: resident WebGPU device texture readback smoke timed out'));
          }, SPH_NATIVE_WEBGPU_SURFACE_VALIDATION_MAP_TIMEOUT_MS);
        })
      ]);
      if (timeoutHandle) clearTimeout(timeoutHandle);
      mapped = true;
      const sample = Array.from(new Uint8Array(readback.getMappedRange(), 0, 4));
      const passed = sample[0] >= 200 && sample[1] <= 32 && sample[2] <= 32 && sample[3] >= 200;
      readback.unmap();
      mapped = false;
      readback.destroy?.();
      validationTexture.destroy?.();
      return publishResidentWebGpuDeviceTextureReadbackSmoke({
        ...statusBase,
        status: passed ? 'passed' : 'failed',
        reason: passed
          ? 'resident WebGPU device texture render/copy/MAP_READ smoke validation passed'
          : 'resident WebGPU device texture render/copy/MAP_READ smoke validation returned an unexpected pixel',
        sample,
        elapsedMs: Math.max(0, nowMs() - startedAtMs),
        updatedAtMs: nowMs()
      });
    } catch (error) {
      if (timeoutHandle) clearTimeout(timeoutHandle);
      if (mapped) {
        try {
          readback?.unmap?.();
        } catch (_) {}
      }
      readback?.destroy?.();
      validationTexture?.destroy?.();
      const reason = error instanceof Error ? error.message : String(error);
      return publishResidentWebGpuDeviceTextureReadbackSmoke({
        ...statusBase,
        status: isNativeWebGpuTextureReadbackUnavailableReason(reason) ? 'not-run' : 'error',
        reason,
        elapsedMs: Math.max(0, nowMs() - startedAtMs),
        updatedAtMs: nowMs()
      });
    }
  }

  function clearCachedOpticalGpuDeviceResult({
    device = null,
    requestPromise = null
  } = {}) {
    if (requestPromise && opticalGpuDeviceResultPromise !== requestPromise) return false;
    if (device && opticalGpuDeviceResultDevice !== device) return false;
    opticalGpuDeviceResultPromise = null;
    opticalGpuDeviceResultDevice = null;
    return true;
  }

  function requestCachedOpticalGpuDevice(ref = navigatorRef) {
    const rendererDeviceResult = admitSphSceneWebGpuDeviceResult(
      rendererOwnedWebGpuDeviceResult() || nativeWebGpuSurfaceConsumerDeviceResult()
    );
    if (rendererDeviceResult?.device) return Promise.resolve(rendererDeviceResult);
    if (
      renderer?.isWebGPURenderer
      && renderer.userData?.sphWebGpuPresentationEnabled !== false
      && !rendererReady
      && rendererInitPromise
    ) {
      return rendererInitPromise.then(() => {
        const readyRendererDeviceResult = admitSphSceneWebGpuDeviceResult(
          rendererOwnedWebGpuDeviceResult()
        );
        if (readyRendererDeviceResult?.device) return readyRendererDeviceResult;
        return requestCachedOpticalGpuDevice(ref);
      });
    }
    if (!opticalGpuDeviceResultPromise) {
      const requestPromise = requestOpticalGpuDevice(ref, {
        timestampProfilingRequested: enableResidentGpuTimestampProfiling
      }).then((requestedResult) => {
        const result = admitSphSceneWebGpuDeviceResult(requestedResult);
        result.rendererBackend = rendererBackendName();
        result.rendererOwnedDevice = false;
        result.rendererOwnedResidentDevicePolicy = scene.userData.sphThreeWebGpuRendererOwnedResidentDevicePolicy
          || resolveThreeWebGpuRendererOwnedResidentDevicePolicy({
            renderer,
            requested: enableThreeWebGpuResidentDevice,
            unsafeDiagnosticOverride: renderer.userData?.sphWebGpuPresentationUnsafeDiagnosticOverride
          });
        if (!result.device) {
          clearCachedOpticalGpuDeviceResult({ requestPromise });
          result.transientDeviceUnavailable = result.reason === 'requestAdapter returned null';
          return result;
        }
        if (opticalGpuDeviceResultPromise === requestPromise) {
          opticalGpuDeviceResultDevice = result.device;
        }
        if (result.device?.lost?.then) {
          result.device.lost.finally(() => {
            clearCachedOpticalGpuDeviceResult({
              device: result.device,
              requestPromise
            });
          }).catch(() => {});
        }
        if (useNativeWebGpuRenderer && result.device && !result.mapSmokePromise) {
          result.mapSmokePromise = runResidentWebGpuDeviceMapSmoke(result.device, {
            source: 'cached-resident-webgpu-device'
          });
          result.textureReadbackSmokePromise = Promise.resolve(result.mapSmokePromise)
            .then(() => runResidentWebGpuDeviceTextureReadbackSmoke(result.device, {
              source: 'cached-resident-webgpu-device'
            }));
        }
        return result;
      }).catch((error) => {
        clearCachedOpticalGpuDeviceResult({ requestPromise });
        return {
          status: 'webgpu-error-fallback',
          reason: error instanceof Error ? error.message : String(error),
          device: null,
          rendererBackend: rendererBackendName(),
          rendererOwnedDevice: false,
          rendererOwnedResidentDevicePolicy: scene.userData.sphThreeWebGpuRendererOwnedResidentDevicePolicy
            || resolveThreeWebGpuRendererOwnedResidentDevicePolicy({
              renderer,
              requested: enableThreeWebGpuResidentDevice,
              unsafeDiagnosticOverride: renderer.userData?.sphWebGpuPresentationUnsafeDiagnosticOverride
            })
        };
      });
      opticalGpuDeviceResultPromise = requestPromise;
    }
    return opticalGpuDeviceResultPromise;
  }

  async function refreshOpticalGpuLookup({
    preferWebGpu = preferWebGpuOpticalLookup,
    force = false,
    skipWhenNoDrawTargets = false,
    skipForWorkerOwnedParticleStatePresentation = false,
    navigatorRef: overrideNavigatorRef = navigatorRef,
    device = null,
    deviceResult = null,
    parityTolerance = 1e-6,
    webGpuRunner = undefined,
    publicationGuard = null
  } = {}) {
    const opticalLookupPublicationIsCurrent = () => {
      if (typeof publicationGuard !== 'function') return true;
      try {
        return publicationGuard() === true;
      } catch {
        return false;
      }
    };
    const generation = opticalGpuLookupGeneration;
    const currentTable = opticalGpuTable;
    const currentLookup = opticalGpuLookup;
    const signature = currentLookup.signature;
    const targetSignature = currentOpticalGpuDrawTargetSignature();
    const noDrawTargets = targetSignature === 'no-optical-gpu-draw-targets';
    const cachedExecution = currentLookup.execution;
    if (!opticalLookupPublicationIsCurrent()) {
      return {
        ...currentLookup,
        execution: {
          ...(cachedExecution || {}),
          status: 'optical-gpu-lookup-refresh-stale',
          stale: true
        }
      };
    }
    if (
      !force
      && cachedExecution?.signature === signature
      && !(cachedExecution.opticalLookupSkippedNoDrawTargets && !noDrawTargets)
      && !(cachedExecution.opticalLookupSkippedWorkerOwnedPresentation && !skipForWorkerOwnedParticleStatePresentation)
    ) {
      return currentLookup;
    }
    if (skipForWorkerOwnedParticleStatePresentation) {
      const execution = {
        schema: 'peercompute.ulg.optical-gpu-lookup-execution.v0',
        lookupResultSchema: currentLookup.lookup?.schema ?? null,
        backend: 'skipped-worker-owned-particle-state-presentation',
        status: 'optical-gpu-lookup-skipped-worker-owned-particle-state-presentation',
        reason: 'worker-owned particle-state producer owns the visible canvas; main-thread optical draw-target updates are not on the presentation path',
        signature,
        targetSignature,
        queryCount: 0,
        outputs: new Float32Array(),
        opticalLookupSkippedWorkerOwnedPresentation: true,
        webgpuStatus: {
          status: 'not-requested',
          reason: 'worker-owned particle-state presentation path'
        },
        scientificValidation: false,
        fullPhysicsValidation: false
      };
      opticalGpuLookup = {
        ...currentLookup,
        execution
      };
      scene.userData.opticalGpuLookup = opticalGpuLookup;
      scene.userData.opticalGpuLookupExecution = execution;
      scene.userData.opticalGpuLookupDrawState = {
        schema: 'peercompute.ulg.optical-gpu-draw-state.v0',
        sourceExecutionSchema: execution.schema,
        sourceExecutionSignature: signature,
        backend: execution.backend,
        status: 'optical-gpu-draw-state-skipped-worker-owned-presentation',
        appliedCount: 0,
        targetSignature,
        targetCount: targetSignature === 'no-optical-gpu-draw-targets'
          ? 0
          : targetSignature.split('|').length,
        rows: [],
        scientificValidation: false,
        fullPhysicsValidation: false
      };
      return opticalGpuLookup;
    }
    if (!force && pendingOpticalGpuLookup?.signature === signature) {
      return pendingOpticalGpuLookup.promise;
    }
    if (skipWhenNoDrawTargets && noDrawTargets) {
      const execution = {
        schema: 'peercompute.ulg.optical-gpu-lookup-execution.v0',
        lookupResultSchema: currentLookup.lookup?.schema ?? null,
        backend: 'skipped-no-draw-targets',
        status: 'optical-gpu-lookup-skipped-no-draw-targets',
        reason: 'worker-owned presentation path has no main-thread optical draw targets',
        signature,
        targetSignature,
        queryCount: 0,
        outputs: new Float32Array(),
        opticalLookupSkippedNoDrawTargets: true,
        webgpuStatus: {
          status: 'not-requested',
          reason: 'no main-thread optical draw targets'
        },
        scientificValidation: false,
        fullPhysicsValidation: false
      };
      opticalGpuLookup = {
        ...currentLookup,
        execution
      };
      scene.userData.opticalGpuLookup = opticalGpuLookup;
      scene.userData.opticalGpuLookupExecution = execution;
      scene.userData.opticalGpuLookupDrawState = {
        schema: 'peercompute.ulg.optical-gpu-draw-state.v0',
        sourceExecutionSchema: execution.schema,
        sourceExecutionSignature: signature,
        backend: execution.backend,
        status: 'optical-gpu-draw-state-skipped-no-targets',
        appliedCount: 0,
        targetSignature,
        targetCount: 0,
        rows: [],
        scientificValidation: false,
        fullPhysicsValidation: false
      };
      return opticalGpuLookup;
    }
    const promise = (async () => {
      const resolvedDeviceResult = preferWebGpu && !device && !deviceResult
        ? await requestCachedOpticalGpuDevice(overrideNavigatorRef)
        : deviceResult;
      const execution = await runOpticalGpuLookupWithOptionalWebGpu({
        table: currentTable,
        lookup: currentLookup.lookup,
        cpuReference: currentLookup.cpuReference,
        preferWebGpu,
        navigatorRef: overrideNavigatorRef,
        device,
        deviceResult: resolvedDeviceResult,
        parityTolerance,
        webGpuRunner,
        onDeviceLost() {
          clearCachedOpticalGpuDeviceResult({
            device: device || resolvedDeviceResult?.device || null
          });
        }
      });
      execution.signature = signature;
      if (
        !running
        || generation !== opticalGpuLookupGeneration
        || opticalGpuLookup.signature !== signature
        || !opticalLookupPublicationIsCurrent()
      ) {
        return {
          ...currentLookup,
          execution: {
            ...execution,
            stale: true
          }
        };
      }
      opticalGpuLookup = {
        ...currentLookup,
        execution
      };
      scene.userData.opticalGpuLookup = opticalGpuLookup;
      scene.userData.opticalGpuLookupExecution = execution;
      applyOpticalGpuLookupExecution(execution, opticalGpuLookup);
      return opticalGpuLookup;
    })();
    pendingOpticalGpuLookup = { signature, promise };
    try {
      return await promise;
    } finally {
      if (pendingOpticalGpuLookup?.promise === promise) pendingOpticalGpuLookup = null;
    }
  }

