    const sphSignature = sphGpuParticleSignature(sphParticleState);
    const mlsSignature = mlsMpmGpuParticleSignature(mlsMpmParticleState);
    if (!sphSignature || !mlsSignature) return null;
    return [
      sphSignature,
      mlsSignature,
      dt,
      gravityMPerS2.join(','),
      dims.join(',')
    ].join('|');
