        mesh.userData.minParticleRadiusM = Number.isFinite(groupMinRadius) ? groupMinRadius : fallbackSphereRadius;
        mesh.userData.maxParticleRadiusM = Number.isFinite(groupMaxRadius) ? groupMaxRadius : fallbackSphereRadius;
