        schema,
        status: bridgeStatus,
        rendererBridge,
        visibleRenderSource,
        reason: null,
        overlayPolicy: resolveSceneResidentSurfaceDrawOverlayPolicy(),
        canvas,
        context,
        device,
        format,
        pipeline,
        cameraBuffer,
        renderRowsBuffer,
