  function markSphResidentRenderProgress(status, extra = {}) {
    const timestampMs = nowMs();
    const progress = {
      schema: 'peercompute.ulg.sph-scene-resident-render-progress.v0',
      status,
      timestampMs,
      ...extra
    };
    scene.userData.sphResidentRenderProgress = progress;
    const cadenceTimelineEvents = globalThis.__ulgSphCadenceTimelineEvents;
    if (Array.isArray(cadenceTimelineEvents)) {
      recordOptInSphCadenceTimelineEvent(
        cadenceTimelineEvents,
        'resident-render',
        status,
        timestampMs,
        extra
      );
    }
    if (emitResidentRenderProgressConsole) {
      const progressStage = extra.stage || extra.currentStage || null;
      const progressSuffix = [
        progressStage ? `stage=${progressStage}` : null,
        extra.surfaceCount !== undefined ? `surfaces=${extra.surfaceCount}` : null,
        extra.totalFieldCells !== undefined ? `cells=${extra.totalFieldCells}` : null
      ].filter(Boolean).join(' ');
      console.debug?.(
        `[sph-render-progress] ${status}${progressSuffix ? ` ${progressSuffix}` : ''}`
      );
    }
    return progress;
  }

  function recordOptInSphCadenceTimelineEvent(
    events,
    kind,
    status,
    timestampMs,
    extra = {}
  ) {
    if (events.length >= 10_000) return;
    const event = {
      kind: kind ?? null,
      status: status ?? null,
      timestampMs: Number(timestampMs)
    };
    for (const field of [
      'stage',
      'currentStage',
      'scheduleId',
      'laneId',
      'stateKey',
      'stepCount',
      'requestedStepCount',
      'completedStepCount',
      'surfaceCount',
      'totalFieldCells',
      'maxFieldCellCount',
      'nativeMarchingCubesSurfaceTableBudgetStatus',
      'nativeMarchingCubesSurfaceTableMaxResolution',
      'surfaceIndex',
      'surfaceKey',
      'pendingSurfaceCount',
      'submittedSurfaceCount',
      'submitCount',
      'yieldForPresentation',
      'final',
      'candidateGeneration',
      'requestToken'
    ]) {
      const value = extra?.[field];
      if (
        value == null
        || typeof value === 'string'
        || typeof value === 'number'
        || typeof value === 'boolean'
      ) {
        event[field] = value ?? null;
      }
    }
    events.push(event);
  }

